contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address vader,
        address usdv,
        address vault,
        address recipient,
        uint amount,
        string memory type1,
        string memory type2,
        uint oldVotes,
        uint newVotes,
        uint totalWeight
    ) public {
        c.init(vader, usdv, vault);

        // Create a proposal P1 (old) of type1.
        c.newAddressProposal(recipient, type1);
        uint oldID = c.proposalCount();

        // Create a proposal P2 (new) of type2.
        c.newAddressProposal(recipient, type2);
        uint newID = c.proposalCount();

        // Put P1 into finalising state by calling voteProposal; whether it actually
        // finalises depends on state, but we only use the resulting flag as observed.
        c.voteProposal(oldID);

        bool oldFinalising = c.mapPID_finalising(oldID);
        bool newHasMinority = c.hasMinority(newID);
        bool sameType = c.isEqual(bytes(c.mapPID_type(oldID)), bytes(c.mapPID_type(newID)));

        bool reverted;
        try c.cancelProposal(oldID, newID) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool precondition = oldFinalising && (newID != oldID) && newHasMinority && sameType;
        assert(reverted == !precondition);
    }

    receive() external payable {}
}
